head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > editDisplayChar]<br/>마스킹 처리된 범위에 입력값 대신 표시될 문자를 설정합니다.",
    "validation" : [        
        "입력값 대신 표시될 마스킹 문자를 설정합니다.",
        "editFormat 속성에 '{,}'(중괄호) 기호로 설정된 마스크 문자가 있고, 해당 범위에 입력값이 있을때 동작합니다.",
        "값을 설정하지 않으면 마스킹 범위여도 입력값이 그대로 표시됩니다.",
        "editPlaceholderChar 가 설정된 경우 마스킹 범위에 입력값이 없으면 editPlaceholderChar 속성에 설정된 문자가 표시됩니다.",
        "editPlaceholderChar 가 설정된 경우 마스킹 범위에 입력값이 있으면 editDisplayChar 속성에 설정된 문자가 표시됩니다.",
        // "getValue() 메소드로 입력값 조회 시 마스킹 문자가 적용되지 않은 입력값이 반환됩니다.",
        // "마스킹 문자가 적용된 값을 반환 받으려면 getFormattedValue() 메소드를 사용해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_edit = function(target) {    
    let rtn = '';
    let tagName = target.tagName

    if (tagName !== "INPUT") {
        rtn = target.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_text_display = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setValue1_onclick = function (e) {    
    target1.setValue("1111111111111");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
};



// target2
scwin.btn_setValue2_onclick = function (e) {    
    target2.setValue("1111111111111");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
};


// target3
scwin.btn_setValue3_onclick = function (e) {    
    target3.setValue("1111111");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
